                    ]
				]

                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(sanitizeOutput(process.out)).match() }
            )
        }
    }

    test("test-bbmap-clumpify-paired-end - stub") {

        options "-stub"

        when {
            process {
                """
